python3 - <<'EOF'
import re,collections
def dec(n): return re.sub(r'\$([0-9A-F]{2})', lambda m: chr(int(m.group(1),16)), n)
def load(p):
    d=collections.Counter()
    for l in open(p):
        parts=l.split(None,1)
        if len(parts)==2: d[dec(parts[1].strip())]+=int(parts[0])
    return d
for kind in ('made','retain'):
    a=load(f'/work/sites57/6abff86d.{kind}.byfn'); b=load(f'/work/meas/83f9.{kind}.byfn')
    print(f"== {kind}: total 57 {sum(a.values())}  83f9 {sum(b.values())}")
    rises=sorted(((b[k]-a.get(k,0),k) for k in set(a)|set(b)), reverse=True)
    for d,k in rises[:16]: print(f"{d:>+11} 57 {a.get(k,0):>11}  {k[:110]}")
EOF

