fn shape_held() -> ShapeHeld {
    let homes: Cell<List<int>?> = Cell.new(null)
    let files: Cell<List<SourceFileAddress>?> = Cell.new(null)
    let unit_files: Cell<List<int>?> = Cell.new(null)
    let wrappers: Cell<List<FnWrapper>?> = Cell.new(null)
    let units: HashKeyedTable<ReachedUnit> = hash_keyed_table()
    ShapeHeld { homes: homes, files: files, unit_files: unit_files, wrappers: wrappers, units: units }
}''')
rep('''            .At(ShapeAt { source: reach.source, shape: reach.node.record_in(reach.source, 0) }),''','''            .At(ShapeAt { source: reach.source, shape: reach.node.record_in(reach.source, 0), held: shape_held() }),''')
rep('''    fn unit(at: int) -> ReachedUnit {
        ReachedUnit
            .read_from(
                self.source,
                ReachedProgram.units_in_place(self.source, self.shape).record_in(self.source, at),
            )
    }''','''    fn unit(at: int) -> ReachedUnit {
        let held = self.held.units.get_at(at, 0)
        if held != null { return held! }
        let read = ReachedUnit
            .read_from(
                self.source,
                ReachedProgram.units_in_place(self.source, self.shape).record_in(self.source, at),
            )
        self.held.units.put_at(at, 0, read)
        read
    }''')
rep('''    fn homes() -> List<int> { ReachedProgram.homes_in(self.source, self.shape) }''','''    fn homes() -> List<int> {
        let held? = self.held.homes.get() else {
            let read = ReachedProgram.homes_in(self.source, self.shape)
            self.held.homes.set(read)
            return read
        }
        held
    }''')
rep('''    fn files() -> List<SourceFileAddress> { ReachedProgram.files_in(self.source, self.shape) }''','''    fn files() -> List<SourceFileAddress> {
        let held? = self.held.files.get() else {
            let read = ReachedProgram.files_in(self.source, self.shape)
            self.held.files.set(read)
            return read
        }
        held
    }''')
rep('''    fn unit_files() -> List<int> { ReachedProgram.unit_files_in(self.source, self.shape) }''','''    fn unit_files() -> List<int> {
        let held? = self.held.unit_files.get() else {
            let read = ReachedProgram.unit_files_in(self.source, self.shape)
            self.held.unit_files.set(read)
            return read
        }
        held
    }''')
rep('''    fn wrappers() -> List<FnWrapper> { ReachedProgram.wrappers_in(self.source, self.shape) }''','''    fn wrappers() -> List<FnWrapper> {
        let held? = self.held.wrappers.get() else {
            let read = ReachedProgram.wrappers_in(self.source, self.shape)
            self.held.wrappers.set(read)
            return read
        }
        held
    }''')
open(p,'w').write(s)
EOF
