    let item = read_item(engine, file, at)
    answer_parts(read_parts(read_said(item.store, item.stmts)))
}

/// What an item's statements `stmts` in `store` say that its reading back says too: what it writes
/// that the items after it read, whether a builder refused what it read, the names it binds with
/// `let`, and which seats of each fn it declares are `mut`. Said where its tape is made, from the
/// store the tape is written from — the store a reading back fills holds the same refusals, as the
/// tape carries them — so its summary reads them without reading the item back.
fn read_said(store: SyntaxArena, stmts: List<StmtId>) -> ItemReadSaid {
    let externs = [p! for s in stmts for p in [store.extern_parts(s)] if p != null]
    let fns = [p! for s in stmts for p in [store.fn_parts(s)] if p != null]
    ItemReadSaid {
        front: ItemFront {
            binds: [BoundRun { name: n!, mutable: store.stmt(s) is .MutLet || store.is_state_stmt(s) } for s in stmts for n in [store.let_name(s)] if n != null],
            uses: [FrontUse {
                path: u!.path,
                items: u!.items,
                bound: [u!.bound_as(j) for j in 0..u!.items.length],
                exported: store.is_exported(s),
            } for s in stmts for u in [store.use_parts(s)] if u != null],
        },
        refused: store.refusals().any(builder_refused(it)),
        lets: [n! for s in stmts for n in [store.let_name(s)] if n != null],
        seats: [SeatsNamed {
            name: name,
            mutable: if externs.any(it.name == name) { [p.promises.mutable for p in externs.find(it.name == name)!.params] } else { [p.promises.mutable for p in fns.find(it.name == name)!.params] },
        } for name in distinct([p.name for p in externs].concat([p.name for p in fns]))],
    }
}

/// What an item says that its reading back says too (`read_said`).
@derive(Saved)
type ItemReadSaid = { front: ItemFront, refused: bool, lets: List<string>, seats: List<SeatsNamed> }

/// Which seats of the fn `name` are `mut`, in order.
@derive(Saved)
type SeatsNamed = { name: string, mutable: List<bool> }

/// What a tape made before an item said what its reading back says, says: nothing.
fn no_read_said() -> ItemReadSaid { ItemReadSaid { front: ItemFront { binds: [], uses: [] }, refused: false, lets: [], seats: [] } }

/// `said` as parts: `front`, `refused`, `lets`, and `w<name>` for each fn's seats.
fn read_parts(said: ItemReadSaid) -> List<NamedValue> {
    [
        NamedValue { name: FRONT_PART, value: said.front.saved_bytes() },
        NamedValue { name: REFUSED_PART, value: ReadRefused { refused: said.refused }.saved_bytes() },
        NamedValue { name: LETS_PART, value: ItemLets { names: said.lets }.saved_bytes() },
    ]
        .concat([NamedValue { name: seats_part(x.name), value: SeatsMarked { mutable: x.mutable }.saved_bytes() } for x in said.seats])
}

/// The part `name` of what the item `at` of `file` says that its reading back says too: its
/// summary's for a written item, read off its tape; its own read parts' for a generated one.
fn read_part(engine: QueryEngine, file: SourceFileAddress, at: int, name: string) -> Bytes? {
    if generated_rank(at) == null { return item_summary_part(engine, file, at, name) }
    item_read_parts_part(engine, file, at, name)
}'''+s[b+2:]
