/// A `use` line as the items after its own read it: the path it names, the items it lists and
/// binds, and whether it re-exports them. Where it stands is no part of it, so text moving above it
/// in its item moves nothing a later item reads.
@derive(Saved)
type FrontUse = { path: List<string>, items: List<string>, bound: List<string>, exported: bool }

/// What the written item `at` of `file` holds that only its reading back says, in parts: what it
/// writes that the items after it read (`front`), whether a builder refused what it read
/// (`refused`), and for each fn it declares, which of its seats are `mut` (`w<name>`). One answer
/// per item, read back once, cut part by part, so a new body for a fn moves none of its parts.
@cut_parted_query
fn item_read_parts(engine: QueryEngine, file: SourceFileAddress, at: int) -> AnswerParts {
    let item = read_item(engine, file, at)
    let front = ItemFront {
        binds: [BoundRun { name: r.name, mutable: r.mutable } for r in ran_in(item)],
        uses: [FrontUse { path: u.path, items: u.items, bound: u.bound, exported: u.exported } for u in uses_written(item)],
    }
    let externs = [p! for s in item.stmts for p in [item.store.extern_parts(s)] if p != null]
    let fns = [p! for s in item.stmts for p in [item.store.fn_parts(s)] if p != null]
    let names = distinct([p.name for p in externs].concat([p.name for p in fns]))
    let seats = [NamedValue {
        name: seats_part(name),
        value: SeatsMarked {
            mutable: if externs.any(it.name == name) { [p.promises.mutable for p in externs.find(it.name == name)!.params] } else { [p.promises.mutable for p in fns.find(it.name == name)!.params] },
            ),
    )
}

/// The part of `before_parts` saying whether an item before the item `at` runs.
fn runs_part(at: int) -> string { "r${at}" }

/// The part of `before_parts` holding what the items before the item `at` write.
fn front_part(at: int) -> string { "f${at}" }

/// What the items `ids` of `file` write that the items after them read, gathered in order.
fn fronts_gathered(engine: QueryEngine, file: SourceFileAddress, ids: List<int>) -> ItemFront { fronts_joined([item_front(engine, file, i) for i in ids]) }

/// `fronts`, one after another.
fn fronts_joined(fronts: List<ItemFront>) -> ItemFront { ItemFront { binds: flatten([f.binds for f in fronts]), uses: flatten([f.uses for f in fronts]) } }

/// The names a written item declares, each with its face, as its meaning's tape says them.
@derive(Saved)
