/// THE ITEMS OF A FILE BY IDENTITY: each written item's id, in the order the file holds them. An
/// item's id is its own (`item_id_of`), never its place, so an item added or taken away renumbers
/// nothing else, and every question asked of an item by its id stands across it.
@cut_query
export fn item_ids(engine: QueryEngine, file: SourceFileAddress) -> List<int> { [i.id for i in file_items(engine, file)] }

/// Whether `file` has the written item `at`: what an item added or taken away beside it leaves
/// standing.
@cut_query
export fn item_held(engine: QueryEngine, file: SourceFileAddress, at: int) -> bool { item_parts_part(engine, file, held_part(at)) != null }

/// Whether `file` holds a written item at all: what an item added or taken away beside another
/// leaves standing.
@cut_query
export fn holds_items(engine: QueryEngine, file: SourceFileAddress) -> bool { !file_items(engine, file).is_empty() }

/// Where the ids of a file's generated items start: past every written item's (`item_id_of`).
export const GENERATED_FIRST: int = 1099511627776

/// The id of a file's `k`-th generated item, counted from zero in the order made.
export fn generated_id(k: int) -> int { GENERATED_FIRST + k }

/// Where the generated item `at` stands among its file's generated items, counted from zero; absent
/// for a written item's id.
export fn generated_rank(at: int) -> int? { if at < GENERATED_FIRST { null } else { at - GENERATED_FIRST } }

/// The id of the `k`-th of `file`'s generated items where `generated`, else of its written ones.
export fn nth_item_id(engine: QueryEngine, file: SourceFileAddress, generated: bool, k: int) -> int {
    if generated { generated_id(k) } else { item_ids(engine, file)[k] }
}

/// A file's item `at`, with the context it reads under; past the file's items, no text. A saved
/// answer is asked again with the place it was asked at, which an edit may have taken away.
@cut_query
export fn item_under(engine: QueryEngine, file: SourceFileAddress, at: int) -> ItemUnder {
    let part = item_parts_part(engine, file, text_part(at))
    let item = if part == null { ItemPart { text: "", print: fp_str("") } } else { ItemPart.from_saved_bytes(part!) }
    ItemUnder {
        text: item.text,
        context: WordShapes.from_saved_bytes(file_context(engine, file)).named_in(item.text),
        print: item.print,
    }
}

/// That a file holds an item: the same for every item, so its part moves only where the item comes or
/// goes.
@derive(Saved)
